<script setup>
import {ref,reactive,onActivated} from 'vue'
import {http,allRows} from '../api/http'
import {ElMessage} from 'element-plus'
import {useDirty} from '../stores/dirty'
import {auth} from '../stores/auth'
import {download} from '../api/download'
const props=defineProps({personal:Boolean})
const personal=auth.user?.role==='EMPLOYEE'
const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`
const rows=ref([]),summary=ref([]),total=ref(0),busy=ref(false),employees=ref([]),departments=ref([]),dialog=ref(false),editing=ref(null),saving=ref(false)
const filter=reactive({month,keyword:'',status:null,employee_id:null,department_id:null,attendance_date:null,page:1,page_size:10})
const form=reactive({employee_id:null,attendance_date:'',clock_in:'',clock_out:'',status:'normal'})
const statuses={normal:'正常',late:'迟到',early_leave:'早退',absent:'缺勤',leave:'请假'}
const resetDirty=useDirty(()=>form,()=>dialog.value)
const base=()=>personal?'/employee/attendance':'/attendance'
async function load(){busy.value=true;try{const r=await http.get(base(),{params:filter});rows.value=r.data;total.value=r.total;summary.value=(await http.get(base()+'/monthly',{params:filter})).data;if(!personal)departments.value=await allRows('/departments')}catch{}finally{busy.value=false}}
async function open(row){editing.value=row;Object.assign(form,{employee_id:row?.employee_id||null,attendance_date:row?.attendance_date||'',clock_in:row?.clock_in||'',clock_out:row?.clock_out||'',status:row?.status||'normal'});try{employees.value=await allRows('/employees');dialog.value=true;await Promise.resolve();resetDirty()}catch{}}
async function save(){if(!form.employee_id||!form.attendance_date){ElMessage.warning('请选择员工和日期');return}saving.value=true;try{const body={...form,clock_in:form.clock_in||null,clock_out:form.clock_out||null};if(editing.value)await http.patch('/attendance/'+editing.value.id,body);else await http.post('/attendance',body);dialog.value=false;resetDirty();ElMessage.success('考勤已保存');load()}catch{}finally{saving.value=false}}
function search(){filter.page=1;load()}
onActivated(load)
</script>
<template><div class="page-title"><div><h1>{{personal?'个人考勤':'考勤管理'}}</h1><p>考勤仅按实际记录统计，不自动将未录入日期视为缺勤。</p></div><div v-if="!personal"><el-button @click="download('/attendance/export',filter,'月度考勤')">导出 Excel</el-button><el-button type="primary" @click="open(null)">录入考勤</el-button></div></div><el-card shadow="never"><el-form inline class="filters"><el-form-item label="月份"><el-date-picker v-model="filter.month" type="month" value-format="YYYY-MM" :clearable="false"/></el-form-item><el-form-item v-if="!personal" label="员工姓名"><el-input v-model="filter.keyword" placeholder="员工姓名" clearable/></el-form-item><el-form-item v-if="!personal" label="部门"><el-select v-model="filter.department_id" clearable><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="filter.attendance_date" value-format="YYYY-MM-DD" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="filter.status" clearable><el-option v-for="(name,key) in statuses" :key="key" :label="name" :value="key"/></el-select></el-form-item><el-button @click="search">查询</el-button><el-button @click="Object.assign(filter,{month,keyword:'',status:null,department_id:null,attendance_date:null});search()">重置</el-button></el-form><el-table v-loading="busy" :data="rows" empty-text="暂无考勤记录"><el-table-column prop="employee_code" label="员工编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="attendance_date" label="日期"/><el-table-column prop="clock_in" label="上班时间"/><el-table-column prop="clock_out" label="下班时间"/><el-table-column label="状态"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column v-if="!personal" label="操作"><template #default="{row}"><el-button link type="primary" :disabled="row.source==='leave'" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="filter.page" :page-size="filter.page_size" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><el-card shadow="never" class="skills-card"><h3>{{filter.month}} 月度汇总</h3><el-table :data="summary"><el-table-column prop="name" label="姓名"/><el-table-column v-for="(name,key) in statuses" :key="key" :prop="key" :label="name"/></el-table></el-card><WorkspaceDialog v-model="dialog" :title="editing?'编辑考勤':'录入考勤'" width="550px" destroy-on-close><el-form label-position="top"><el-form-item label="员工" required><el-select v-model="form.employee_id"><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="e.name+' · '+e.employee_code"/></el-select></el-form-item><el-form-item label="考勤日期" required><el-date-picker v-model="form.attendance_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="上班时间"><el-time-picker v-model="form.clock_in" value-format="HH:mm:ss"/></el-form-item><el-form-item label="下班时间"><el-time-picker v-model="form.clock_out" value-format="HH:mm:ss"/></el-form-item><el-form-item label="考勤状态" required><el-select v-model="form.status"><el-option v-for="(name,key) in statuses" :key="key" :value="key" :label="name"/></el-select></el-form-item><el-button type="primary" :loading="saving" @click="save">保存考勤</el-button></el-form></WorkspaceDialog></template>
